CREATE TABLE projects(id BIGSERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,description TEXT,status VARCHAR(20) NOT NULL CHECK(status IN ('PLANNING','IN_PROGRESS','COMPLETED','ON_HOLD')),progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),tech_stack VARCHAR(500),start_date DATE,target_date DATE,notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE project_milestones(id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title VARCHAR(255) NOT NULL,description TEXT,completed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
